class Solution:
    def maxFrequencyScore(self, nums, k):
        nums.sort()
        n = len(nums)
        P = [0] * (n + 1)
        for i, x in enumerate(nums):
            P[i + 1] = P[i] + x
        def cost(i, j):
            m = i + (j - i) // 2
            med = nums[m]
            return med * (m - i) - (P[m] - P[i]) + (P[j + 1] - P[m + 1]) - med * (j - m)
        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if any(cost(i, i + mid - 1) <= k for i in range(n - mid + 1)):
                lo = mid
            else:
                hi = mid - 1
        return lo

