class Solution {
public:
    int maxFrequencyScore(vector<int>& nums, long long k) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<long long> P(n + 1, 0);
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        auto cost = [&](int i, int j) {
            int m = i + (j - i) / 2;
            long long med = nums[m];
            return med * (m - i) - (P[m] - P[i]) + (P[j + 1] - P[m + 1]) - med * (j - m);
        };
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            bool ok = false;
            for (int i = 0; i + mid <= n; i++)
                if (cost(i, i + mid - 1) <= k) { ok = true; break; }
            if (ok) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
};

