            int mid = (lo + hi + 1) / 2;
            boolean ok = false;
            for (int i = 0; i + mid <= n; i++) {
                int m = i + (mid - 1) / 2;
                long med = nums[m];
                long c = med * (m - i) - (P[m] - P[i]) + (P[i + mid] - P[m + 1]) - med * (i + mid - 1 - m);
