class Solution {
    public int maxFrequencyScore(int[] nums, long k) {
        Arrays.sort(nums);
        int n = nums.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        int l = 0, best = 1;
        for (int r = 0; r < n; r++) {
            while (true) {
                int m = l + (r - l) / 2;
                long med = nums[m];
                long c = med * (m - l) - (P[m] - P[l]) + (P[r + 1] - P[m + 1]) - med * (r - m);
                if (c <= k) break;
                l++;
            }
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

